fn is_html_file(filename: Str) -> Bool {
  return filename.contains(".html");
}

fn extract_username(email: Str) -> Str {
  let at_pos = email.index_of("@");
  match at_pos {
    Some(pos) => { return str_slice(email, 0, pos); }
    None => { return ""; }
  }
}

fn main() -> Int {
  let username = extract_username("alice@example.com");
  return username.len();
}
